<?php require_once __DIR__.'/../app/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['delete'])){db()->prepare('DELETE FROM ads WHERE id=?')->execute([(int)$_POST['delete']]);flash('success','Publicidad eliminada.');}else{$img=upload_image('image','ads');db()->prepare('INSERT INTO ads(title,image,target_url,position,active) VALUES(?,?,?,?,1)')->execute([trim($_POST['title']),$img,trim($_POST['target_url']),$_POST['position']==='banner'?'banner':'sidebar']);flash('success','Publicidad creada.');}redirect('../admin/ads.php');}$ads=db()->query('SELECT * FROM ads ORDER BY id DESC')->fetchAll();$adminPage='ads';$adminTitle='Publicidad interna';$adminSubtitle='Banners propios, campañas y enlaces promocionales';require __DIR__.'/partials/header.php';?>
<div class="admin-grid cols-2"><section class="panel-card mt-0"><div class="panel-head"><div><h2>➕ Nueva campaña</h2><p>Crea publicidad propia independiente de AdSense.</p></div></div><form method="post" enctype="multipart/form-data" class="admin-form"><?=csrf_field()?><label>Título<input name="title" required></label><label class="mt-20">Enlace de destino<input type="url" name="target_url"></label><label class="mt-20">Imagen<input type="file" name="image" accept="image/*"></label><label class="mt-20">Posición<select name="position"><option value="sidebar">Lateral</option><option value="banner">Banner horizontal</option></select></label><button class="admin-btn mt-20">📣 Crear publicidad</button></form></section><section class="panel-card mt-0"><div class="panel-head"><div><h2>Campañas creadas</h2><p><?=count($ads)?> elementos</p></div></div><?php foreach($ads as $a):?><div class="health-row"><div><b><?=e($a['title'])?></b><small style="display:block;color:#6b7785"><?=e($a['position'])?></small></div><form method="post"><?=csrf_field()?><button class="admin-btn small danger" name="delete" value="<?=$a['id']?>" data-confirm="¿Eliminar esta publicidad?">Eliminar</button></form></div><?php endforeach;?></section></div>
<?php require __DIR__.'/partials/footer.php';?>
